# Created: 2026-09-02

#!/usr/bin/env python3
"""
write-proof-report.py

Renders `<name>.proofread.md` for the proofread pipeline (today's
src/skills/proofread/SKILL.md Step 6 shape, generalized to the 3-stage
editorial/language/mechanical pipeline in the v0.7.0 plan of record).

The report has four parts, in order:
  (a) A Gates table with one row per pipeline stage -- stage, ran/skipped,
      why, model, rounds, outcome. Every stage appears, including ones that
      were skipped: VER-10/SPC-14 require a bypassed gate to be labelled,
      never silently omitted.
  (b) The editorial memo (verbatim prose, or an explicit "no memo" line).
  (c) One applied-changes table per stage that has at least one applied
      change, each row carrying its rationale.
  (d) Flags and notes: every change with `applied: false` (idea-flags,
      citation-guard downgrades, refuted, no-match/ambiguous, comment-only),
      together with its `skipReason` -- so nothing dropped along the way
      becomes invisible in the report.

An empty change list renders a clean pass and lists no applied changes
(VER-08 negative case) -- this is not an error, it is the expected shape
for an already-clean article.

Input contract (this script's own JSON shape -- not changes-schema.json,
which only covers the `changes` array; see --input below):

    {
      "filebase": "my-article",
      "source": "articles/my-article.md",
      "correctedCopy": "articles/my-article.proofed.md",
      "language": "he",
      "profile": "loaded" | "none",
      "date": "2026-09-02",
      "gates": [
        {"stage": "editorial", "ran": true, "why": "...", "model": "opus",
         "rounds": 1, "outcome": "5 findings"},
        {"stage": "mechanical", "ran": false, "why": "no checker available",
         "model": null, "rounds": null, "outcome": "skipped"}
      ],
      "memo": "free-text editorial memo, or null/omitted",
      "changes": [ <changes-schema.json change objects, each stage's own> ]
    }

Usage:
    python3 write-proof-report.py --input report-input.json --out article.proofread.md [--json]

--input   Path to a JSON file matching the input contract above.
--out     Path to write the rendered markdown report to. If omitted, the
          markdown is printed to stdout instead of being written to disk
          (no writes outside the path given).
--json    Also print a JSON summary object to stdout (written path, applied/
          flagged counts, clean-pass flag) -- the house convention for
          scripts in this directory.

Exit code 0 on success, 2 on a usage/IO/JSON error.
No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Optional

STAGE_ORDER = ["editorial", "language", "mechanical"]


def _stage_sort_key(stage: str) -> int:
    try:
        return STAGE_ORDER.index(stage)
    except ValueError:
        return len(STAGE_ORDER)


def _md_escape(value) -> str:
    if value is None:
        return "—"
    text = str(value)
    return text.replace("|", "\\|").replace("\n", " ")


def render_gates_table(gates: list[dict]) -> str:
    lines = [
        "## Gates",
        "",
        "| Stage | Ran | Why | Model | Rounds | Outcome |",
        "|---|---|---|---|---|---|",
    ]
    if not gates:
        lines.append("| — | — | no gates recorded | — | — | — |")
    else:
        for gate in gates:
            ran = gate.get("ran")
            ran_cell = "yes" if ran else "no (skipped)"
            lines.append(
                "| {stage} | {ran} | {why} | {model} | {rounds} | {outcome} |".format(
                    stage=_md_escape(gate.get("stage")),
                    ran=ran_cell,
                    why=_md_escape(gate.get("why")),
                    model=_md_escape(gate.get("model")),
                    rounds=_md_escape(gate.get("rounds")),
                    outcome=_md_escape(gate.get("outcome")),
                )
            )
    return "\n".join(lines)


def render_memo(memo: Optional[str]) -> str:
    lines = ["## Editorial memo", ""]
    if memo and memo.strip():
        lines.append(memo.strip())
    else:
        lines.append("_No editorial memo for this run._")
    return "\n".join(lines)


def render_applied_tables(changes: list[dict]) -> str:
    applied = [c for c in changes if c.get("applied") is True]
    lines = ["## Applied changes", ""]
    if not applied:
        lines.append("_No changes were applied — clean pass._")
        return "\n".join(lines)

    by_stage: dict[str, list[dict]] = {}
    for change in applied:
        by_stage.setdefault(change.get("stage", "unknown"), []).append(change)

    for stage in sorted(by_stage, key=_stage_sort_key):
        stage_changes = by_stage[stage]
        lines.append(f"### {stage}")
        lines.append("")
        lines.append("| # | Line | Level | Type | Before → After | Why |")
        lines.append("|---|------|-------|------|----------------|-----|")
        for idx, change in enumerate(stage_changes, start=1):
            before_after = f"`{_md_escape(change.get('before'))}` → `{_md_escape(change.get('after'))}`"
            lines.append(
                "| {n} | {line} | {level} | {type_} | {before_after} | {why} |".format(
                    n=idx,
                    line=_md_escape(change.get("line")),
                    level=_md_escape(change.get("level")),
                    type_=_md_escape(change.get("type")),
                    before_after=before_after,
                    why=_md_escape(change.get("rationale")),
                )
            )
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def render_flags_and_notes(changes: list[dict]) -> str:
    flagged = [c for c in changes if c.get("applied") is False]
    lines = ["## Flags and notes", ""]
    if not flagged:
        lines.append("_No flags._")
        return "\n".join(lines)

    lines.append("| # | Stage | Line | Type | Skip reason | Rationale |")
    lines.append("|---|-------|------|------|-------------|-----------|")
    for idx, change in enumerate(flagged, start=1):
        lines.append(
            "| {n} | {stage} | {line} | {type_} | {reason} | {rationale} |".format(
                n=idx,
                stage=_md_escape(change.get("stage")),
                line=_md_escape(change.get("line")),
                type_=_md_escape(change.get("type")),
                reason=_md_escape(change.get("skipReason")),
                rationale=_md_escape(change.get("rationale")),
            )
        )
    return "\n".join(lines)


def build_report(data: dict) -> str:
    changes = data.get("changes", [])
    applied_count = sum(1 for c in changes if c.get("applied") is True)
    flagged_count = sum(1 for c in changes if c.get("applied") is False)

    header = [
        f"# Proofread report — {data.get('filebase', 'untitled')}",
        "",
        f"- Source: `{data.get('source', '—')}`",
        f"- Corrected copy: `{data.get('correctedCopy', '—')}`",
        f"- Language: {data.get('language', '—')} · Profile: {data.get('profile', 'none')}",
        f"- Applied: {applied_count} total · Flagged (not applied): {flagged_count}",
        f"- Date: {data.get('date', '—')}",
    ]
    if not changes:
        header.append("- Status: clean pass — no changes recorded")

    sections = [
        "\n".join(header),
        render_gates_table(data.get("gates", [])),
        render_memo(data.get("memo")),
        render_applied_tables(changes),
        render_flags_and_notes(changes),
    ]
    return "\n\n".join(sections).rstrip() + "\n"


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Render the proofread pipeline's <name>.proofread.md change report."
    )
    parser.add_argument(
        "--input", required=True, help="Path to a JSON file matching this script's input contract."
    )
    parser.add_argument(
        "--out",
        default=None,
        help="Path to write the rendered markdown to. If omitted, prints markdown to stdout.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Also print a JSON summary object to stdout.",
    )
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        data = json.loads(Path(args.input).read_text(encoding="utf-8"))
    except OSError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(json.dumps({"error": f"invalid JSON in --input: {exc}"}), file=sys.stderr)
        return 2

    report_md = build_report(data)

    written_path = None
    if args.out:
        out_path = Path(args.out)
        out_path.write_text(report_md, encoding="utf-8")
        written_path = str(out_path)
    else:
        print(report_md)

    if args.json or args.out:
        changes = data.get("changes", [])
        summary = {
            "written": written_path,
            "appliedCount": sum(1 for c in changes if c.get("applied") is True),
            "flaggedCount": sum(1 for c in changes if c.get("applied") is False),
            "gatesCount": len(data.get("gates", [])),
            "cleanPass": len(changes) == 0,
        }
        print(json.dumps(summary, ensure_ascii=False))

    return 0


if __name__ == "__main__":
    sys.exit(main())
